class Solution {
    public int[] getStrongest(int[] arr, int k) {
        int n = arr.length;
        int[] s = arr.clone();
        Arrays.sort(s);
        int m = s[(n - 1) / 2];
        Integer[] boxed = new Integer[n];
        for (int i = 0; i < n; i++) boxed[i] = arr[i];
        Arrays.sort(boxed, (a, b) -> {
            int da = Math.abs(a - m), db = Math.abs(b - m);
            if (da != db) return db - da;
            return b - a;
        });
        int[] res = new int[k];
        for (int i = 0; i < k; i++) res[i] = boxed[i];
        return res;
    }
}

