class Solution {
public:
    vector<int> getStrongest(vector<int>& arr, int k) {
        sort(arr.begin(), arr.end());
        int m = arr[(arr.size() - 1) / 2];
        vector<int> res;
        int l = 0, r = arr.size() - 1;
        while ((int)res.size() < k) {
            if (abs(arr[l] - m) > abs(arr[r] - m)) res.push_back(arr[l++]);
            else res.push_back(arr[r--]);
        }
        return res;
    }
};

